static inline void ConvertRGBToXYZ(const double red,const double green,
  const double blue,double *X,double *Y,double *Z)
{
  double
    b,
    g,
    r;

  /*
    Convert RGB to XYZ colorspace.
  */
  assert(X != (double *) NULL);
  assert(Y != (double *) NULL);
  assert(Z != (double *) NULL);
  r=QuantumScale*DecodePixelGamma(red);
  g=QuantumScale*DecodePixelGamma(green);
  b=QuantumScale*DecodePixelGamma(blue);
  *X=0.4124564*r+0.3575761*g+0.1804375*b;
  *Y=0.2126729*r+0.7151522*g+0.0721750*b;
  *Z=0.0193339*r+0.1191920*g+0.9503041*b;
}

void DecodePngV2(OpKernelContext* context, StringPiece input) {
  int channel_bits = (data_type_ == DataType::DT_UINT8) ? 8 : 16;
  png::DecodeContext decode;
  OP_REQUIRES(
      context, png::CommonInitDecode(input, channels_, channel_bits, &decode),
      errors::InvalidArgument("Invalid PNG. Failed to initialize decoder."));

  // Verify that width and height are not too large:
  // - verify width and height don't overflow int.
  // - width can later be multiplied by channels_ and sizeof(uint16), so
  //   verify single dimension is not too large.
  // - verify when width and height are multiplied together, there are a few
  //   bits to spare as well.
  const int width = static_cast<int>(decode.width);
  const int height = static_cast<int>(decode.height);
  const int64_t total_size =
      static_cast<int64_t>(width) * static_cast<int64_t>(height);
  if (width != static_cast<int64_t>(decode.width) || width <= 0 ||
      width >= (1LL << 27) || height != static_cast<int64_t>(decode.height) ||
      height <= 0 || height >= (1LL << 27) || total_size >= (1LL << 29)) {
    OP_REQUIRES(context, false,
                errors::InvalidArgument("PNG size too large for int: ",
                                        decode.width, " by ", decode.height));
  }

  Tensor* output = nullptr;
  // By the existing API, we support decoding PNG with `DecodeGif` op.
  // We need to make sure to return 4-D shapes when using `DecodeGif`.
  if (op_type_ == "DecodeGif") {
    OP_REQUIRES_OK(
        context,
        context->allocate_output(
            0, TensorShape({1, height, width, decode.channels}), &output));
  } else {
    OP_REQUIRES_OK(
        context,
        context->allocate_output(
            0, TensorShape({height, width, decode.channels}), &output));
  }

  if (op_type_ == "DecodeBmp") {
    // TODO(b/171060723): Only DecodeBmp as op_type_ is not acceptable here
    // because currently `decode_(jpeg|png|gif)` ops can decode any one of
    // jpeg, png or gif but not bmp. Similarly, `decode_bmp` cannot decode
    // anything but bmp formats. This behavior needs to be revisited. For more
    // details, please refer to the bug.
    OP_REQUIRES(context, false,
                errors::InvalidArgument(
                    "Trying to decode PNG format using DecodeBmp op. Use "
                    "`decode_png` or `decode_image` instead."));
  } else if (op_type_ == "DecodeAndCropJpeg") {
    OP_REQUIRES(context, false,
                errors::InvalidArgument(
                    "DecodeAndCropJpeg operation can run on JPEG only, but "
                    "detected PNG."));
  }

  if (data_type_ == DataType::DT_UINT8) {
    OP_REQUIRES(
        context,
        png::CommonFinishDecode(
            reinterpret_cast<png_bytep>(output->flat<uint8>().data()),
            decode.channels * width * sizeof(uint8), &decode),
        errors::InvalidArgument("Invalid PNG data, size ", input.size()));
  } else if (data_type_ == DataType::DT_UINT16) {
    OP_REQUIRES(
        context,
        png::CommonFinishDecode(
            reinterpret_cast<png_bytep>(output->flat<uint16>().data()),
            decode.channels * width * sizeof(uint16), &decode),
        errors::InvalidArgument("Invalid PNG data, size ", input.size()));
  } else if (data_type_ == DataType::DT_FLOAT) {
    // `png::CommonFinishDecode` does not support `float`. First allocate
    // uint16 buffer for the image and decode in uint16 (lossless). Wrap the
    // buffer in `unique_ptr` so that we don't forget to delete the buffer.
    std::unique_ptr<uint16[]> buffer(
        new uint16[height * width * decode.channels]);
    OP_REQUIRES(
        context,
        png::CommonFinishDecode(reinterpret_cast<png_bytep>(buffer.get()),
                                decode.channels * width * sizeof(uint16),
                                &decode),
        errors::InvalidArgument("Invalid PNG data, size ", input.size()));

    // Convert uint16 image data to desired data type.
    // Use eigen threadpooling to speed up the copy operation.
    const auto& device = context->eigen_device<Eigen::ThreadPoolDevice>();
    TTypes<uint16, 3>::UnalignedConstTensor buf(buffer.get(), height, width,
                                                decode.channels);
    float scale = 1. / std::numeric_limits<uint16>::max();
    // Fill output tensor with desired dtype.
    output->tensor<float, 3>().device(device) = buf.cast<float>() * scale;
  }
}

static void rom_reset(void *unused)
{
    Rom *rom;

    QTAILQ_FOREACH(rom, &roms, next) {
        if (rom->fw_file) {
            continue;
        }
        if (rom->data == NULL) {
            continue;
        }
        if (rom->mr) {
            void *host = memory_region_get_ram_ptr(rom->mr);
            memcpy(host, rom->data, rom->datasize);
        } else {
            address_space_write_rom(rom->as, rom->addr, MEMTXATTRS_UNSPECIFIED,
                                    rom->data, rom->datasize);
        }
        if (rom->isrom) {
            /* rom needs to be written only once */
            g_free(rom->data);
            rom->data = NULL;
        }
        /*
         * The rom loader is really on the same level as firmware in the guest
         * shadowing a ROM into RAM. Such a shadowing mechanism needs to ensure
         * that the instruction cache for that new region is clear, so that the
         * CPU definitely fetches its instructions from the just written data.
         */
        cpu_flush_icache_range(rom->addr, rom->datasize);
    }
}

static PixelChannels **AcquirePixelThreadSet(const Image *images)
{
  const Image
    *next;

  PixelChannels
    **pixels;

  register ssize_t
    i;

   size_t
     columns,
    number_threads;

  number_threads=(size_t) GetMagickResourceLimit(ThreadResource);
  pixels=(PixelChannels **) AcquireQuantumMemory(number_threads,
    sizeof(*pixels));
   if (pixels == (PixelChannels **) NULL)
     return((PixelChannels **) NULL);
  (void) memset(pixels,0,number_threads*sizeof(*pixels));
  columns=images->columns;
   for (next=images; next != (Image *) NULL; next=next->next)
     columns=MagickMax(next->columns,columns);
  for (i=0; i < (ssize_t) number_threads; i++)
   {
     register ssize_t
       j;

    pixels[i]=(PixelChannels *) AcquireQuantumMemory(columns,sizeof(**pixels));
    if (pixels[i] == (PixelChannels *) NULL)
      return(DestroyPixelThreadSet(pixels));
    for (j=0; j < (ssize_t) columns; j++)
    {
      register ssize_t
        k;

      for (k=0; k < MaxPixelChannels; k++)
        pixels[i][j].channel[k]=0.0;
    }
  }
  return(pixels);
}

void ScriptProcessorHandler::Process(size_t frames_to_process) {

  AudioBus* input_bus = Input(0).Bus();
  AudioBus* output_bus = Output(0).Bus();

  unsigned double_buffer_index = this->DoubleBufferIndex();
  bool is_double_buffer_index_good =
      double_buffer_index < 2 && double_buffer_index < input_buffers_.size() &&
      double_buffer_index < output_buffers_.size();
  DCHECK(is_double_buffer_index_good);
  if (!is_double_buffer_index_good)
    return;

  AudioBuffer* input_buffer = input_buffers_[double_buffer_index].Get();
  AudioBuffer* output_buffer = output_buffers_[double_buffer_index].Get();

  unsigned number_of_input_channels = internal_input_bus_->NumberOfChannels();
  bool buffers_are_good =
      output_buffer && BufferSize() == output_buffer->length() &&
      buffer_read_write_index_ + frames_to_process <= BufferSize();

  if (internal_input_bus_->NumberOfChannels())
    buffers_are_good = buffers_are_good && input_buffer &&
                       BufferSize() == input_buffer->length();

  DCHECK(buffers_are_good);
  if (!buffers_are_good)
    return;

  bool is_frames_to_process_good = frames_to_process &&
                                   BufferSize() >= frames_to_process &&
                                   !(BufferSize() % frames_to_process);
  DCHECK(is_frames_to_process_good);
  if (!is_frames_to_process_good)
    return;

  unsigned number_of_output_channels = output_bus->NumberOfChannels();

  bool channels_are_good =
      (number_of_input_channels == number_of_input_channels_) &&
      (number_of_output_channels == number_of_output_channels_);
  DCHECK(channels_are_good);
  if (!channels_are_good)
    return;

  for (unsigned i = 0; i < number_of_input_channels; ++i)
    internal_input_bus_->SetChannelMemory(
        i,
        input_buffer->getChannelData(i).View()->Data() +
            buffer_read_write_index_,
        frames_to_process);

  if (number_of_input_channels)
    internal_input_bus_->CopyFrom(*input_bus);

  for (unsigned i = 0; i < number_of_output_channels; ++i) {
    memcpy(output_bus->Channel(i)->MutableData(),
           output_buffer->getChannelData(i).View()->Data() +
               buffer_read_write_index_,
           sizeof(float) * frames_to_process);
  }

  buffer_read_write_index_ =
      (buffer_read_write_index_ + frames_to_process) % BufferSize();

  if (!buffer_read_write_index_) {
    MutexTryLocker try_locker(process_event_lock_);
    if (!try_locker.Locked()) {
      output_buffer->Zero();
    } else if (Context()->GetExecutionContext()) {
      if (Context()->HasRealtimeConstraint()) {
         TaskRunnerHelper::Get(TaskType::kMediaElementEvent,
                               Context()->GetExecutionContext())
            ->PostTask(
                BLINK_FROM_HERE,
                CrossThreadBind(&ScriptProcessorHandler::FireProcessEvent,
                                WrapRefPtr(this), double_buffer_index_));
       } else {
        std::unique_ptr<WaitableEvent> waitable_event =
            WTF::MakeUnique<WaitableEvent>();

         TaskRunnerHelper::Get(TaskType::kMediaElementEvent,
                               Context()->GetExecutionContext())
            ->PostTask(
                BLINK_FROM_HERE,
                CrossThreadBind(&ScriptProcessorHandler::
                                    FireProcessEventForOfflineAudioContext,
                                WrapRefPtr(this), double_buffer_index_,
                                CrossThreadUnretained(waitable_event.get())));

        waitable_event->Wait();
      }
    }

    SwapBuffers();
  }
}

TIFFReadRawStrip1(TIFF* tif, uint32 strip, void* buf, tmsize_t size,
    const char* module)
{
	TIFFDirectory *td = &tif->tif_dir;

    if (!_TIFFFillStriles( tif ))
        return ((tmsize_t)(-1));

	assert((tif->tif_flags&TIFF_NOREADRAW)==0);
	if (!isMapped(tif)) {
		tmsize_t cc;

		if (!SeekOK(tif, td->td_stripoffset[strip])) {
			TIFFErrorExt(tif->tif_clientdata, module,
			    "Seek error at scanline %lu, strip %lu",
			    (unsigned long) tif->tif_row, (unsigned long) strip);
			return ((tmsize_t)(-1));
		}
		cc = TIFFReadFile(tif, buf, size);
		if (cc != size) {
#if defined(__WIN32__) && (defined(_MSC_VER) || defined(__MINGW32__))
			TIFFErrorExt(tif->tif_clientdata, module,
		"Read error at scanline %lu; got %I64u bytes, expected %I64u",
				     (unsigned long) tif->tif_row,
				     (unsigned __int64) cc,
				     (unsigned __int64) size);
#else
			TIFFErrorExt(tif->tif_clientdata, module,
		"Read error at scanline %lu; got %llu bytes, expected %llu",
				     (unsigned long) tif->tif_row,
				     (unsigned long long) cc,
				     (unsigned long long) size);
#endif
			return ((tmsize_t)(-1));
		}
	} else {
		tmsize_t ma,mb;
		tmsize_t n;
		ma=(tmsize_t)td->td_stripoffset[strip];
		mb=ma+size;
		if (((uint64)ma!=td->td_stripoffset[strip])||(ma>tif->tif_size))
			n=0;
		else if ((mb<ma)||(mb<size)||(mb>tif->tif_size))
			n=tif->tif_size-ma;
		else
			n=size;
		if (n!=size) {
#if defined(__WIN32__) && (defined(_MSC_VER) || defined(__MINGW32__))
			TIFFErrorExt(tif->tif_clientdata, module,
	"Read error at scanline %lu, strip %lu; got %I64u bytes, expected %I64u",
				     (unsigned long) tif->tif_row,
				     (unsigned long) strip,
				     (unsigned __int64) n,
				     (unsigned __int64) size);
#else
			TIFFErrorExt(tif->tif_clientdata, module,
	"Read error at scanline %lu, strip %lu; got %llu bytes, expected %llu",
				     (unsigned long) tif->tif_row,
				     (unsigned long) strip,
				     (unsigned long long) n,
				     (unsigned long long) size);
#endif
			return ((tmsize_t)(-1));
		}
		_TIFFmemcpy(buf, tif->tif_base + ma,
			    size);
	}
	return (size);
}

