void Compute(OpKernelContext* ctx) override {
  const Tensor& gradient = ctx->input(0);
  const Tensor& input = ctx->input(1);
  Tensor* input_backprop = nullptr;
  OP_REQUIRES_OK(ctx,
                 ctx->allocate_output(0, input.shape(), &input_backprop));
  OP_REQUIRES(
      ctx, axis_ >= -1,
      errors::InvalidArgument("Axis must be at least -1. Found ", axis_));
  OP_REQUIRES(ctx, (axis_ == -1 || axis_ < input.shape().dims()),
              errors::InvalidArgument(
                  "Axis should be -1 or 0 or a positive value less than ",
                  input.shape().dims(), "but given axis value was ", axis_));

  OP_REQUIRES(
      ctx, input.IsSameSize(gradient),
      errors::InvalidArgument("gradient and input must be the same size"));
  const int depth = (axis_ == -1) ? 1 : input.dim_size(axis_);
  const Tensor& input_min_tensor = ctx->input(2);
  OP_REQUIRES(ctx,
              input_min_tensor.dims() == 0 || input_min_tensor.dims() == 1,
              errors::InvalidArgument(
                  "Input min tensor must have dimension 1. Recieved ",
                  input_min_tensor.dims(), "."));
  const Tensor& input_max_tensor = ctx->input(3);
  OP_REQUIRES(ctx,
              input_max_tensor.dims() == 0 || input_max_tensor.dims() == 1,
              errors::InvalidArgument(
                  "Input max tensor must have dimension 1. Recieved ",
                  input_max_tensor.dims(), "."));
  if (axis_ != -1) {
    OP_REQUIRES(
        ctx, input_min_tensor.dim_size(0) == depth,
        errors::InvalidArgument("min has incorrect size, expected ", depth,
                                " was ", input_min_tensor.dim_size(0)));
    OP_REQUIRES(
        ctx, input_max_tensor.dim_size(0) == depth,
        errors::InvalidArgument("max has incorrect size, expected ", depth,
                                " was ", input_max_tensor.dim_size(0)));
  }

  TensorShape min_max_shape(input_min_tensor.shape());
  Tensor* input_min_backprop;
  OP_REQUIRES_OK(ctx,
                 ctx->allocate_output(1, min_max_shape, &input_min_backprop));

  Tensor* input_max_backprop;
  OP_REQUIRES_OK(ctx,
                 ctx->allocate_output(2, min_max_shape, &input_max_backprop));

  if (axis_ == -1) {
    functor::QuantizeAndDequantizeOneScaleGradientFunctor<Device, T> f;
    f(ctx->eigen_device<Device>(), gradient.template flat<T>(),
      input.template flat<T>(), input_min_tensor.scalar<T>(),
      input_max_tensor.scalar<T>(), input_backprop->template flat<T>(),
      input_min_backprop->template scalar<T>(),
      input_max_backprop->template scalar<T>());
  } else {
    functor::QuantizeAndDequantizePerChannelGradientFunctor<Device, T> f;
    f(ctx->eigen_device<Device>(),
      gradient.template flat_inner_outer_dims<T, 3>(axis_ - 1),
      input.template flat_inner_outer_dims<T, 3>(axis_ - 1),
      &input_min_tensor, &input_max_tensor,
      input_backprop->template flat_inner_outer_dims<T, 3>(axis_ - 1),
      input_min_backprop->template flat<T>(),
      input_max_backprop->template flat<T>());
  }
}

void png_print_chunk(unsigned type, unsigned char* data, unsigned size)
{
	char tag[5];
	unsigned i;

	be_uint32_write(tag, type);
	tag[4] = 0;

	cout << tag << setw(8) << size;

	switch (type) {
		case ADV_MNG_CN_MHDR :
			cout << " width:" << be_uint32_read(data+0) << " height:" << be_uint32_read(data+4) << " frequency:" << be_uint32_read(data+8);
			cout << " simplicity:" << be_uint32_read(data+24);
			cout << "(bit";
			for(i=0;i<32;++i) {
				if (be_uint32_read(data+24) & (1 << i)) {
					cout << "," << i;
				}
			}
			cout << ")";
		break;
		case ADV_MNG_CN_DHDR :
			cout << " id:" << be_uint16_read(data+0);
			switch (data[2]) {
				case 0 : cout << " img:unspecified"; break;
				case 1 : cout << " img:png"; break;
				case 2 : cout << " img:jng"; break;
				default: cout << " img:?"; break;
			}
			switch (data[3]) {
				case 0 : cout << " delta:entire_replacement"; break;
				case 1 : cout << " delta:block_addition"; break;
				case 2 : cout << " delta:block_alpha_addition"; break;
				case 3 : cout << " delta:block_color_addition"; break;
				case 4 : cout << " delta:block_replacement"; break;
				case 5 : cout << " delta:block_alpha_replacement"; break;
				case 6 : cout << " delta:block_color_replacement"; break;
				case 7 : cout << " delta:no_change"; break;
				default: cout << " delta:?"; break;
			}
			if (size >= 12) {
				cout << " width:" << be_uint32_read(data + 4) << " height:" << be_uint32_read(data + 8);
			}
			if (size >= 20) {
				cout << " x:" << (int)be_uint32_read(data + 12) << " y:" << (int)be_uint32_read(data + 16);
			}
		break;
		case ADV_MNG_CN_FRAM :
			if (size >= 1) {
				cout << " mode:" << (unsigned)data[0];
			}
			if (size > 1) {
				i = 1;
				while (i < size && data[i]!=0)
					++i;
				cout << " len:" << i-1;

				if (size >= i+2) {
					cout << " delay_mode:" << (unsigned)data[i+1];
				}

				if (size >= i+3) {
					cout << " timeout:" << (unsigned)data[i+2];
				}

				if (size >= i+4) {
					cout << " clip:" << (unsigned)data[i+3];
				}

				if (size >= i+5) {
					cout << " syncid:" << (unsigned)data[i+4];
				}

				if (size >= i+9) {
					cout << " tick:" << be_uint32_read(data+i+5);
				}

				if (size >= i+13) {
					cout << " timeout:" << be_uint32_read(data+i+9);
				}

				if (size >= i+14) {
					cout << " dt:" << (unsigned)data[i+10];
				}

				if (size >= i+15) {
					cout << " ...";
				}
			}
			break;
		case ADV_MNG_CN_DEFI :
			cout << " id:" << be_uint16_read(data+0);
			if (size >= 3) {
				switch (data[2]) {
					case 0 : cout << " visible:yes"; break;
					case 1 : cout << " visible:no"; break;
					default : cout << " visible:?"; break;
				}
			}
			if (size >= 4) {
				switch (data[3]) {
					case 0 : cout << " concrete:abstract"; break;
					case 1 : cout << " concrete:concrete"; break;
					default : cout << " concrete:?"; break;
				}
			}
			if (size >= 12) {
				cout << " x:" << (int)be_uint32_read(data + 4) << " y:" << (int)be_uint32_read(data + 8);
			}
			if (size >= 28) {
				cout << " left:" << be_uint32_read(data + 12) << " right:" << be_uint32_read(data + 16) << " top:" << be_uint32_read(data + 20) << " bottom:" << be_uint32_read(data + 24);
			}
		break;
		case ADV_MNG_CN_MOVE :
			cout << " id_from:" << be_uint16_read(data+0) << " id_to:" << be_uint16_read(data+2);
			switch (data[4]) {
				case 0 : cout << " type:replace"; break;
				case 1 : cout << " type:add"; break;
				default : cout << " type:?"; break;
			}
			cout << " x:" << (int)be_uint32_read(data + 5) << " y:" << (int)be_uint32_read(data + 9);
			break;
		case ADV_MNG_CN_PPLT :
			switch (data[0]) {
				case 0 : cout << " type:replacement_rgb"; break;
				case 1 : cout << " type:delta_rgb"; break;
				case 2 : cout << " type:replacement_alpha"; break;
				case 3 : cout << " type:delta_alpha"; break;
				case 4 : cout << " type:replacement_rgba"; break;
				case 5 : cout << " type:delta_rgba"; break;
				default : cout << " type:?"; break;
			}
			i = 1;
			while (i<size) {
				unsigned ssize;
				cout << " " << (unsigned)data[i] << ":" << (unsigned)data[i+1];
				if (data[0] == 0 || data[1] == 1)
					ssize = 3;
				else if (data[0] == 2 || data[1] == 3)
					ssize = 1;
				else
					ssize = 4;
				i += 2 + (data[i+1] - data[i] + 1) * ssize;
			}
			break;
		case ADV_PNG_CN_IHDR :
			cout << " width:" << be_uint32_read(data) << " height:" << be_uint32_read(data + 4);
			cout << " depth:" << (unsigned)data[8];
			cout << " color_type:" << (unsigned)data[9];
			cout << " compression:" << (unsigned)data[10];
			cout << " filter:" << (unsigned)data[11];
			cout << " interlace:" << (unsigned)data[12];
		break;
	}

	cout << endl;
}

static int originates_from_local_legacy_unicast_socket(AvahiServer *s, const AvahiAddress *address, uint16_t port) {
    assert(s);
    assert(address);
    assert(port > 0);

    if (!s->config.enable_reflector)
        return 0;

    if (!avahi_address_is_local(s->monitor, address))
        return 0;

    if (address->proto == AVAHI_PROTO_INET && s->fd_legacy_unicast_ipv4 >= 0) {
        struct sockaddr_in lsa;
        socklen_t l = sizeof(lsa);

        if (getsockname(s->fd_legacy_unicast_ipv4, (struct sockaddr*) &lsa, &l) != 0)
            avahi_log_warn("getsockname(): %s", strerror(errno));
        else
            return lsa.sin_port == port;

    }

    if (address->proto == AVAHI_PROTO_INET6 && s->fd_legacy_unicast_ipv6 >= 0) {
        struct sockaddr_in6 lsa;
        socklen_t l = sizeof(lsa);

        if (getsockname(s->fd_legacy_unicast_ipv6, (struct sockaddr*) &lsa, &l) != 0)
            avahi_log_warn("getsockname(): %s", strerror(errno));
        else
            return lsa.sin6_port == port;
    }

    return 0;
}

